$t['Automatic setup creates the webhook for this site URL only, or adds the missing events to it and keeps any other events. It saves the Webhook ID used to verify signatures. It never deletes webhooks, never touches other URLs and never changes the app permissions.'] = 'Den automatiska konfigurationen skapar webhooken endast för den här webbplatsens URL, eller lägger till saknade händelser i den och behåller övriga händelser. Den sparar det webhook-ID som används för att verifiera signaturer. Den tar aldrig bort webhooks, rör aldrig andra URL:er och ändrar aldrig appens behörigheter.';
$t['Automatic setup needs Webhook Endpoints: Write. It creates the webhook and securely saves its new signing secret, or enables the existing endpoint and adds missing events. It preserves existing events and does not replace endpoints or change API key permissions.'] = 'Den automatiska konfigurationen kräver Webhook Endpoints: Write. Den skapar webhooken och sparar dess nya signeringshemlighet säkert, eller aktiverar den befintliga slutpunkten och lägger till saknade händelser. Befintliga händelser behålls och slutpunkter ersätts inte, och API-nyckelns behörigheter ändras inte.';
