$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Webbplatsens dagliga uppladdningskvot för YouTube har nåtts. Uppladdningar blir tillgängliga igen efter midnatt Pacific Time. Försök igen senare.';
